// @vitest-environment node
/**
 * `key_authenticity` section of shared/protocol/schemas/clipboard-vectors.json (generated by the Go backend,
 * docs/CLIPBOARD_PROTOCOL.md §1 "Key authenticity"). The Web library must reproduce every value from the shared
 * `chain` inputs (ADK v1, ADK v2, chain blob) and accept the published signatures.
 */
import { readFileSync } from 'node:fs';
import { sha256 } from '@noble/hashes/sha2.js';
import { describe, expect, it } from 'vitest';
import {
  SIGN_INFO,
  anchorKeyBytes,
  anchorKeyFromSeed,
  anchorMessage,
  checkDeviceKeyProof,
  deviceKeyMessage,
  deviceKeyProof,
  assertRecoveryKeySigned,
  recoveryAnchor,
  recoveryKeyMessage,
  recoveryKeySignature,
  rotationMessage,
  signSeed,
  signWithAdk,
  verifyKeyOf,
  verifySignature,
} from './authenticity';
import { b64uEncode, fromHex, hex, utf8 } from './encoding';

const PATH = new URL('../../../../shared/protocol/schemas/clipboard-vectors.json', import.meta.url).pathname;

interface Vectors {
  chain: { adk_v1: string; adk_v2: string; blob: string; key_version: number };
  key_authenticity: {
    info_sign: string;
    sign_seed_v1: string;
    verify_key_v1: string;
    sign_seed_v2: string;
    verify_key_v2: string;
    rotation: { key_version: number; chain_blob_sha256: string; message_utf8: string; signature: string };
    device_key: { device_id: string; key_version: number; public_key: string; message_utf8: string; proof: string };
    anchor: { recovery_seed: string; anchor_key: string; message_utf8: string; recovery_anchor: string };
    recovery_key: { public_key: string; message_utf8: string; signature: string };
  };
}

const vectors = JSON.parse(readFileSync(PATH, 'utf8')) as Vectors;
const ka = vectors.key_authenticity;
const adkV1 = fromHex(vectors.chain.adk_v1);
const adkV2 = fromHex(vectors.chain.adk_v2);
const chainBlob = fromHex(vectors.chain.blob);

describe('clipboard-vectors.json key_authenticity', () => {
  it('derives the signing seeds and verify keys of both versions', async () => {
    expect(ka.info_sign).toBe(SIGN_INFO);
    expect(hex(await signSeed(adkV1))).toBe(ka.sign_seed_v1);
    expect(hex(await signSeed(adkV2))).toBe(ka.sign_seed_v2);
    expect(hex(await verifyKeyOf(adkV1))).toBe(ka.verify_key_v1);
    expect(hex(await verifyKeyOf(adkV2))).toBe(ka.verify_key_v2);
  });

  it('builds the rotation message and reproduces and accepts the rotation signature', async () => {
    const r = ka.rotation;
    expect(r.key_version).toBe(vectors.chain.key_version);
    expect(hex(sha256(chainBlob))).toBe(r.chain_blob_sha256);
    const message = rotationMessage(r.key_version, fromHex(ka.verify_key_v2), chainBlob);
    expect(message).toBe(r.message_utf8);
    // Ed25519 is deterministic: signing with version 1 gives the published bytes.
    expect(hex(await signWithAdk(adkV1, utf8(message)))).toBe(r.signature);
    expect(verifySignature(fromHex(r.signature), utf8(message), fromHex(ka.verify_key_v1))).toBe(true);
    expect(verifySignature(fromHex(r.signature), utf8(message), fromHex(ka.verify_key_v2))).toBe(false);
  });

  it('builds the device key message and reproduces and accepts the proof', async () => {
    const d = ka.device_key;
    const pub = fromHex(d.public_key);
    expect(deviceKeyMessage(d.device_id, d.key_version, pub)).toBe(d.message_utf8);
    expect(deviceKeyMessage(d.device_id.toUpperCase(), d.key_version, pub)).toBe(d.message_utf8);
    const reg = await deviceKeyProof(adkV1, d.key_version, d.device_id, pub);
    expect(reg).toEqual({
      public_key: b64uEncode(pub),
      key_version: d.key_version,
      proof: b64uEncode(fromHex(d.proof)),
    });
    const vk = fromHex(ka.verify_key_v1);
    expect(checkDeviceKeyProof(vk, d.device_id, d.key_version, reg.public_key, reg.proof)).toBe(true);
    // Bound to the device ID, version and key.
    expect(checkDeviceKeyProof(vk, '00000000-0000-4000-8000-000000000002', 1, reg.public_key, reg.proof)).toBe(false);
    expect(checkDeviceKeyProof(vk, d.device_id, 2, reg.public_key, reg.proof)).toBe(false);
  });

  it('derives the anchor key and the recovery anchor', async () => {
    const a = ka.anchor;
    const seed = fromHex(a.recovery_seed);
    expect(hex(await anchorKeyBytes(seed))).toBe(a.anchor_key);
    expect(anchorMessage(fromHex(ka.verify_key_v1))).toBe(a.message_utf8);
    expect(hex(await recoveryAnchor(await anchorKeyFromSeed(seed), fromHex(ka.verify_key_v1)))).toBe(a.recovery_anchor);
  });

  it('builds the recovery key message and reproduces and accepts the setup signature (contract H.5)', async () => {
    const r = ka.recovery_key;
    const pub = fromHex(r.public_key);
    expect(recoveryKeyMessage(pub)).toBe(r.message_utf8);
    expect(hex(await recoveryKeySignature(adkV1, pub))).toBe(r.signature);
    const vk1 = fromHex(ka.verify_key_v1);
    expect(verifySignature(fromHex(r.signature), utf8(r.message_utf8), vk1)).toBe(true);
    expect(verifySignature(fromHex(r.signature), utf8(r.message_utf8), fromHex(ka.verify_key_v2))).toBe(false);
    const sig = b64uEncode(fromHex(r.signature));
    expect(() => assertRecoveryKeySigned(b64uEncode(pub), sig, vk1)).not.toThrow();
    const other = pub.slice();
    other[0] = (other[0] ?? 0) ^ 1;
    expect(() => assertRecoveryKeySigned(b64uEncode(other), sig, vk1)).toThrow(
      expect.objectContaining({ code: 'unverified' }),
    );
  });
});
